import{_ as e,c as a,o as i,aj as n}from"./chunks/framework.CDhdelVI.js";const p=JSON.parse('{"title":"Yield Planner","description":"Use the Yield Planner to size pieces by count or grams, and estimate batch yield.","frontmatter":{"title":"Yield Planner","description":"Use the Yield Planner to size pieces by count or grams, and estimate batch yield.","head":[["meta",{"name":"description","content":"Use the Yield Planner to size pieces by count or grams, and estimate batch yield."}],["meta",{"property":"og:title","content":"Yield Planner"}],["meta",{"property":"og:description","content":"Use the Yield Planner to size pieces by count or grams, and estimate batch yield."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/guides/yield-planner.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Yield Planner"}],["meta",{"name":"twitter:description","content":"Use the Yield Planner to size pieces by count or grams, and estimate batch yield."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/guides/yield-planner.html"}]]},"headers":[],"relativePath":"guides/yield-planner.md","filePath":"guides/yield-planner.md"}'),r={name:"guides/yield-planner.md"};function l(o,t,s,d,c,h){return i(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="yield-planner" tabindex="-1">Yield Planner <a class="header-anchor" href="#yield-planner" aria-label="Permalink to “Yield Planner”">​</a></h1><p>The Yield Planner is your batch reality check. Pick a mode, set the target you actually care about, and KitchenRatio scales the formula to match. No guesswork, no napkin math.</p><div class="guide-glance"><div class="guide-glance-card"><strong>Best For</strong><span>Sizing portions, rolls, tortillas, and loaf-pan batches more reliably.</span></div><div class="guide-glance-card"><strong>Focus</strong><span>Total dough weight, piece count, and grams-per-piece planning.</span></div><div class="guide-glance-card"><strong>Read This Next</strong><span>Use it alongside the calculator and recipe pages for real batch planning.</span></div></div><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to “Quick Start”">​</a></h2><ol><li>Open <strong>Batch size</strong> from the summary area on mobile, or use the <strong>Batch size</strong> card directly on desktop.</li><li>Choose a mode: <strong>Portions</strong>, <strong>Total dough</strong>, or <strong>Flour</strong>.</li><li>Enter one value and the planner does the rest, instantly.</li></ol><h2 id="pick-the-planning-input" tabindex="-1">Pick the Planning Input <a class="header-anchor" href="#pick-the-planning-input" aria-label="Permalink to “Pick the Planning Input”">​</a></h2><p>If you are planning by portions, use the <strong>Grams each</strong> field to dial in your target piece size directly.<br> If you are planning by total dough, enter the full dough target in grams and let the calculator scale flour to match. If you already know the flour amount you want to use, switch to <strong>Flour</strong> and enter that directly.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The planner sizes the batch you want to make. Depending on mode, your input can be portions, total dough, or flour.</p></div><h2 id="common-starting-weights" tabindex="-1">Common Starting Weights <a class="header-anchor" href="#common-starting-weights" aria-label="Permalink to “Common Starting Weights”">​</a></h2><p>These are solid starting points. Adjust for dough type, hydration, and the finished size you want.</p><table tabindex="0"><thead><tr><th>Item</th><th>Starter weight (g)</th><th>Typical range (g)</th><th>Notes</th></tr></thead><tbody><tr><td>Tortilla (10-12 in, rolled thin)</td><td>47</td><td>40-55</td><td>47g yields a thin 10-12 inch tortilla.</td></tr><tr><td>Dinner roll</td><td>60</td><td>50-80</td><td>Soft dinner rolls, medium size.</td></tr><tr><td>Sandwich roll</td><td>100</td><td>85-120</td><td>For buns or sandwich rolls.</td></tr><tr><td>Hoagie / sub roll</td><td>160</td><td>140-190</td><td>Classic 6-8 inch subs.</td></tr><tr><td>1 lb loaf pan</td><td>454</td><td>430-500</td><td>Starting dough weight for a 1 lb pan.</td></tr><tr><td>1.5 lb loaf pan</td><td>680</td><td>640-760</td><td>Starting dough weight for a 1.5 lb pan.</td></tr><tr><td>2 lb loaf pan</td><td>908</td><td>850-1000</td><td>Starting dough weight for a 2 lb pan.</td></tr></tbody></table><p>Need a scale? <a href="https://amzn.to/48F9DfT" target="_blank" rel="noreferrer">KitchenAid Digital Scale</a>.</p><h2 id="example-plan-tortillas" tabindex="-1">Example: Plan Tortillas <a class="header-anchor" href="#example-plan-tortillas" aria-label="Permalink to “Example: Plan Tortillas”">​</a></h2><ul><li>Flour: <strong>450 g</strong></li><li>Final dough: <strong>~860 g</strong></li><li>Target weight: <strong>47 g</strong></li><li>Result: <strong>18 pieces</strong></li></ul><h2 id="practical-tips" tabindex="-1">Practical Tips <a class="header-anchor" href="#practical-tips" aria-label="Permalink to “Practical Tips”">​</a></h2><ul><li>Weigh your dough for the most accurate yield count.</li><li>Stiffer doughs feel tighter in smaller pieces, while softer doughs can handle slightly larger ones.</li><li>If you change hydration, re-check piece size after a short rest.</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><div class="content-section"><ul><li><a href="/guides/kitchenratio-calculator.html">KitchenRatio Calculator</a></li><li><a href="/guides/hydration.html">Hydration</a></li><li><a href="/recipes/tortillas.html">No-knead Tortillas</a></li></ul></div><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><div class="content-section"><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul></div><blockquote><p><strong>Affiliate Disclaimer</strong><br> This post contains affiliate links. As an Amazon Associate, I earn from qualifying purchases. If you click on a link and make a purchase, I may receive a small commission at no extra cost to you.</p></blockquote>',21)])])}const u=e(r,[["render",l]]);export{p as __pageData,u as default};
